// Ubi — versione inglese dell'interfaccia.
// L'app è scritta in italiano; se la lingua scelta è l'inglese, questo modulo traduce al volo
// i testi dell'interfaccia (testi, pulsanti, segnaposto, avvisi) con il dizionario qui sotto.
// NON traduce i contenuti degli utenti né le curiosità: restano nella lingua in cui sono stati scritti.
// Per aggiungere una frase: ['testo italiano esatto', 'English text'].
//   '^testo' = vale solo a inizio frase (es. «Ciao Andrea»), 'testo$' = solo a fine frase.
//   Le frasi corte (una parola) vengono tradotte solo se sono l'intero testo di un elemento.

const KEY = 'ubi_lang';
try { const q = new URLSearchParams(location.search).get('lang'); if (q === 'en' || q === 'it') localStorage.setItem(KEY, q); } catch { /* */ }
const saved = (() => { try { return localStorage.getItem(KEY); } catch { return null; } })();
export const LANG = saved === 'it' || saved === 'en' ? saved : (/^it\b/i.test(navigator.language || 'it') ? 'it' : 'en');
export const LOC = LANG === 'en' ? 'en-GB' : 'it-IT';
export function setLang(l) { try { localStorage.setItem(KEY, l); } catch { /* */ } location.reload(); }

