// ——— motore
const WHOLE = new Map(), START = [], END = [], LONG = new Map();
for (const [k, v] of D) {
  if (k.startsWith('^')) START.push([k.slice(1), v]);
  else if (k.endsWith('$') && k.length > 1) END.push([k.slice(0, -1), v]);
  else { WHOLE.set(k, v); if (k.length >= 10 && /\s/.test(k)) LONG.set(k, v); }
}
const reEsc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const LONG_RE = LONG.size ? new RegExp([...LONG.keys()].sort((a, b) => b.length - a.length).map(reEsc).join('|'), 'g') : null;
START.sort((a, b) => b[0].length - a[0].length);

export function tr(s) {
  if (LANG !== 'en' || s == null) return s;
  const str = String(s).replace(/\s+/g, ' ');
  const t = str.trim();
  if (!t || !/[A-Za-zÀ-ù]/.test(t)) return str;
  if (WHOLE.has(t)) return str.replace(t, () => WHOLE.get(t));
  let out = str;
  for (const [re, rep] of R) out = out.replace(re, rep);
  for (const [k, v] of START) {
    const lead = out.match(/^\s*/)[0];
    if (out.startsWith(k, lead.length) && !/[A-Za-zÀ-ù]/.test(out.charAt(lead.length + k.length) || ' ')) { out = lead + v + out.slice(lead.length + k.length); break; }
  }
  for (const [k, v] of END) if (out.trimEnd().endsWith(k)) { out = out.replace(new RegExp(reEsc(k) + '(\\s*)$'), v + '$1'); break; }
  if (LONG_RE) out = out.replace(LONG_RE, (m) => LONG.get(m));
  return out;
}

// Contenuti degli utenti e curiosità: non si traducono.
const SKIP = '[translate="no"], .textbody, .hint, .bio, .bubble, .chip.static, .adtxt, .item .t, .reply .t, script, style, textarea, .leaflet-control-attribution';
const ATTRS = ['placeholder', 'title', 'aria-label', 'alt'];
const done = new WeakMap();

function fixText(n) {
  const p = n.parentElement;
  if (!p || p.closest(SKIP)) return;
  const v = n.nodeValue;
  if (done.get(n) === v) return;
  const o = tr(v);
  if (o !== v) n.nodeValue = o;
  done.set(n, o);
}
function fixEl(el) {
  if (el.closest(SKIP)) return;
  for (const a of ATTRS) {
    const v = el.getAttribute(a);
    if (v) { const o = tr(v); if (o !== v) el.setAttribute(a, o); }
  }
  if (el.tagName === 'A' && el.getAttribute('href') === 'privacy.html') el.setAttribute('href', 'privacy-en.html');
  if (el.tagName === 'INPUT' && /^(button|submit)$/.test(el.type) && el.value) el.value = tr(el.value);
}
function walk(root) {
  if (root.nodeType === 3) { fixText(root); return; }
  if (root.nodeType !== 1) return;
  if (root.closest && root.closest(SKIP)) return;
  fixEl(root);
  const it = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT, {
    acceptNode: (x) => (x.nodeType === 1 && x.matches(SKIP) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT),
  });
  let x;
  while ((x = it.nextNode())) { if (x.nodeType === 3) fixText(x); else fixEl(x); }
}

function langLink() {
  const f = document.querySelector('footer.foot');
  if (!f || f.querySelector('#langsw')) return;
  const a = document.createElement('a');
  a.href = '#'; a.id = 'langsw'; a.setAttribute('translate', 'no');
  a.textContent = LANG === 'en' ? '🇮🇹 Italiano' : '🇬🇧 English';
  a.addEventListener('click', (e) => { e.preventDefault(); setLang(LANG === 'en' ? 'it' : 'en'); });
  f.insertBefore(document.createTextNode(' · '), f.querySelector('br'));
  f.insertBefore(a, f.querySelector('br'));
}

export function startI18n() {
  document.documentElement.lang = LANG;
  langLink();
  if (LANG !== 'en') return;
  document.title = 'Ubi — leave a memory where it was born';
  const md = document.querySelector('meta[name="description"]');
  if (md) md.content = 'Pin photos, videos and audio to a place: they unlock only when you get there.';
  for (const f of ['alert', 'confirm', 'prompt']) {
    const orig = window[f].bind(window);
    window[f] = (m, ...r) => orig(tr(m), ...r);
  }
  walk(document.body);
  new MutationObserver((ms) => {
    for (const m of ms) {
      if (m.type === 'characterData') fixText(m.target);
      else if (m.type === 'attributes') fixEl(m.target);
      else m.addedNodes.forEach(walk);
    }
  }).observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ATTRS });
}
